css:
.lf { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.lf-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.lf-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.lf-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.hf { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.hf-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.hf-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.hf-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.hf-help { margin: 6px 0 0; font-size: 12px; line-height: 1.6; color: #6b7280; }

.hz { display: flex; align-items: center; gap: 16px; width: 360px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.hz-label { flex: none; width: 76px; font-size: 13px; font-weight: 600; color: #374151; }
.hz-input { flex: 1; min-width: 0; padding: 10px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.hz-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.rf { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.rf-label { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.rf-badge { padding: 1px 7px; border-radius: 4px; background: #dc2626; color: #fff; font-size: 10px; font-weight: 700; }
.rf-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.rf-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.ef { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ef-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ef-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #ef4444; border-radius: 8px; background: #fef2f2; font-size: 14px; color: #111827; }
.ef-input:focus { outline: none; box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.2); }
.ef-msg { margin: 6px 0 0; font-size: 12px; color: #b91c1c; }

.tc { display: flex; flex-direction: column; gap: 14px; width: 340px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.tc-row { display: flex; gap: 12px; }
.tc-field { flex: 1; min-width: 0; }
.tc-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.tc-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.tc-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.lg { width: 320px; padding: 26px 24px 24px; box-sizing: border-box; background: #fff; border: 1px solid #e5e7eb; border-radius: 14px; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.06); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.lg-title { margin: 0 0 18px; font-size: 20px; color: #111827; }
.lg-field { margin-bottom: 14px; }
.lg-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.lg-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.lg-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.lg-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; font-size: 12px; color: #4b5563; }
.lg-forgot { color: #2563eb; text-decoration: none; }
.lg-btn { width: 100%; padding: 12px 0; border: 0; border-radius: 8px; background: #2563eb; color: #fff; font-size: 14px; font-weight: 700; cursor: pointer; }
.lg-btn:hover { background: #1d4ed8; }

.fgct { width: 340px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.fgct-field { margin-bottom: 14px; }
.fgct-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.fgct-input { display: block; width: 100%; padding: 11px 14px; font-family: inherit; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; }
.fgct-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.fgct-area { resize: vertical; line-height: 1.6; }
.fgct-btn { padding: 12px 28px; border: 0; border-radius: 8px; background: #111827; color: #fff; font-size: 14px; font-weight: 700; cursor: pointer; }
.fgct-btn:hover { background: #374151; }
